# The CSS half of conventions 15 and 16, written into css-src/ where it belongs.
#
# public_html/assets/css/site.css is GENERATED by tools/sync.py from css-src/*.css and
# says so in its first line. A first pass edited the generated file; `sync.py --check`
# caught it. Everything here goes into the source file named in each section banner,
# and tools/sync.py rebuilds site.css afterwards.
#
# LINE ENDINGS: css-src/*.css are LF, the files under public_html are CRLF, and sync.py
# converts on the way out. So every anchor is built with the file's OWN ending, read
# from the file, rather than a hard-coded \r\n — that mistake cost a run here already.

import io, os, sys

ROOT = r"C:/Users/RTX4070TI/Desktop/sanpou-site-v2"
changed = []

def read(p):
    with io.open(os.path.join(ROOT, p), "r", encoding="utf-8", newline="") as f:
        s = f.read()
    return s, ("\r\n" if "\r\n" in s else "\n")

def write(p, s):
    with io.open(os.path.join(ROOT, p), "w", encoding="utf-8", newline="") as f:
        f.write(s)
    if p not in changed:
        changed.append(p)

def sub(s, old, new, what):
    n = s.count(old)
    if n != 1:
        sys.exit("ABORT: %s found %d times, expected 1" % (what, n))
    return s.replace(old, new, 1)

# ---------------------------------------------------------------- 45-home.css
# The news band moved to the foot of main on 2026-11-19 and kept the clothes of its
# old position under the hero: 40px of padding against a section's 96, a 26px heading
# against every other section's 36, and a tint that touched the tinted 会社案内 band
# above it. Deleting the overrides is the fix: .section and the shared h2 are right.
p = "css-src/45-home.css"
s, E = read(p)
s = sub(s,
        "/* ---- news strip, directly under the hero ---- */" + E +
        ".home-news { padding-block: 40px; background: var(--band); }" + E,
        "/* ---- news, at the foot of main since 2026-11-19 (it was a strip under the hero) ---- */" + E,
        "home-news comment and box rule")
s = sub(s, ".home-news-head h2 { font-size: 26px; line-height: 1.4; }" + E, "", "home-news h2 size")
# on a paper section the shared .news-list rule already tints each row
s = sub(s, ".home-news .news-list > li { background: var(--paper); }" + E, "", "home-news row background")
s = sub(s,
        "@media (max-width: 767.98px) { .home-news { padding-block: 32px; } "
        ".home-news-head h2 { font-size: 22px; } }" + E,
        "", "home-news phone overrides")

A = "/* ---- \u4e8b\u696d\u5185\u5bb9: four service cards"
if A not in s:
    sys.exit("ABORT: service-cards banner not found in 45-home.css")
if "#reasons .more-row" in s:
    sys.exit("ABORT: reasons rule already present")
s = s.replace(A,
              "/* \u9078\u3070\u308c\u308b\u7406\u7531: the FAQ link belongs with the button above it, "
              "not a section's distance below */" + E +
              "#reasons .more-row + .more-row { margin-top: 12px; }" + E + E + A, 1)
write(p, s)

# --------------------------------------------------------------- 62-legal.css
p = "css-src/62-legal.css"
s, E = read(p)
ANCHOR = ".lg-sm-page.is-wide { grid-column: 1 / -1; }" + E
if ".sm-home" in s:
    sys.exit("ABORT: .sm-home already present")
s = sub(s, ANCHOR,
        ANCHOR +
        "/* the home row at the top of the sitemap: one card, so it takes far less than a section's height */"
        + E + ".sm-home { padding-block: 28px; }" + E +
        "@media (max-width: 767.98px) { .sm-home { padding-block: 16px; } }" + E,
        "is-wide rule")
write(p, s)

# ------------------------------------------------------------- 65-recruit.css
# 選考の流れ is a procedure and keeps Step 01–04. The career ladder is four vehicle
# classes, and its figure already says ステップアップ; its numbers said nothing the
# rising bars, the growing trucks and the three-step path below did not.
p = "css-src/65-recruit.css"
s, E = read(p)
s = sub(s,
        ".rec-up-no { font-size: 12px; font-weight: 600; line-height: 1.4; "
        "letter-spacing: var(--track-en); text-transform: uppercase; }" + E,
        "", "rec-up-no rule")
s = sub(s, "  .rec-up-no { color: var(--accent-strong); }" + E, "", "rec-up-no phone rule")
write(p, s)

# -------------------------------------------------------- 70-news-contact.css
# The pager already ends with the 「お知らせ一覧へ戻る」 button; the panel beside it
# repeated the same destination. Without that last row the panel needs its padding back.
p = "css-src/70-news-contact.css"
s, E = read(p)
s = sub(s, ".ns-recent-more { margin-top: 4px; }" + E, "", "ns-recent-more rule")
s = sub(s, ".ns-recent { padding: 28px 24px 16px; border-radius: var(--radius); background: var(--band); }",
        ".ns-recent { padding: 28px 24px 24px; border-radius: var(--radius); background: var(--band); }",
        "ns-recent padding")
s = sub(s, "  .ns-recent { padding: 24px 16px 12px; }", "  .ns-recent { padding: 24px 16px 20px; }",
        "ns-recent phone padding")
write(p, s)

print("changed:")
for c in changed:
    print("  " + c)
